   141|async function rest<T>(pathName: string, init: RequestInit = {}, prefer?: string): Promise<T> {
   142|  const response = await fetch(`${getSupabaseUrl()}/rest/v1${pathName}`, {
   143|    ...init,
   144|    headers: { ...headers(prefer), ...(init.headers ?? {}) },
   145|  });
   146|  const text = await response.text();
   147|  let payload: unknown = null;
   148|  try { payload = text ? JSON.parse(text) : null; } catch { payload = text; }
   149|  if (!response.ok) {
   150|    const message =
   151|      payload && typeof payload === 'object'
   152|        ? String((payload as Record<string, unknown>).message ?? (payload as Record<string, unknown>).error ?? `HTTP ${response.status}`)
   153|        : `HTTP ${response.status}`;
   154|    throw new Error(`Supabase members REST ${response.status}: ${message}`);
   155|  }
   156|  return payload as T;
