   183|async function findExisting(input: CanonicalMemberInput): Promise<CanonicalMemberRow | null> {
   184|  const authUserId = (input.authUserId || '').trim();
   185|  if (authUserId) {
   186|    const rows = await rest<CanonicalMemberRow[]>(`/members?auth_user_id=eq.${encodeURIComponent(authUserId)}&limit=1`);
   187|    if (rows.length > 0) return rows[0];
   188|  }
   189|  const landingSubmissionId = (input.landingSubmissionId || '').trim();
   190|  if (landingSubmissionId) {
   191|    const rows = await rest<CanonicalMemberRow[]>(`/members?landing_submission_id=eq.${encodeURIComponent(landingSubmissionId)}&limit=1`);
   192|    if (rows.length > 0) return rows[0];
   193|  }
   194|  const email = normEmail(input.email);
   195|  if (email) {
   196|    const rows = await rest<CanonicalMemberRow[]>(`/members?email=ilike.${encodeURIComponent(email)}&limit=1`);
   197|    if (rows.length > 0) return rows[0];
   198|  }
   199|  const phoneDigits = normPhoneDigits(input.phone);
   200|  if (phoneDigits.length >= 10) {
   201|    const rows = await rest<CanonicalMemberRow[]>(`/members?phone=like.*${encodeURIComponent(phoneDigits.slice(-10))}&limit=1`);
   202|    if (rows.length > 0) return rows[0];
   203|  }
   204|  return null;
