   255|const MEMBERS_STORE_FILE = (): string =>
   256|  path.join(process.cwd(), 'logs', 'audit', 'member-database', 'fallback-members.json');
   257|
   258|async function readMemberStore(): Promise<FallbackMemberStore> {
   259|  const file = MEMBERS_STORE_FILE();
   260|  if (isDurableStoreConfigured()) {
   261|    try {
   262|      return await readDurableJson<FallbackMemberStore>(file, {});
   263|    } catch {
   264|      return {};
   265|    }
   266|  }
   267|  try {
   268|    const raw = await readFile(file, 'utf8');
   269|    return JSON.parse(raw) as FallbackMemberStore;
   270|  } catch {
   271|    return {};
   272|  }
