   275|async function writeMemberStore(store: FallbackMemberStore): Promise<void> {
   276|  const file = MEMBERS_STORE_FILE();
   277|  if (isDurableStoreConfigured()) {
   278|    try {
   279|      await writeDurableJson(file, store);
   280|      return;
   281|    } catch {
   282|      // fall through to filesystem
   283|    }
   284|  }
   285|  await mkdir(path.dirname(file), { recursive: true });
   286|  await writeFile(file, JSON.stringify(store, null, 2), 'utf8');
