   288|
   289|function hashPassword(password: string, salt: string): string {
   290|  return scryptSync(password, salt, 64).toString('hex');
   291|}
   292|
   293|/** Verify a fallback member's credentials. Returns the member id on success. */
   294|export async function verifyFallbackMemberPassword(email: string, password: string): Promise<string | null> {
   295|  const store = await readMemberStore();
   296|  const record = Object.values(store).find((m) => m.email === email.toLowerCase());
   297|  if (!record) return null;
   298|  const candidate = Buffer.from(hashPassword(password, record.passwordSalt), 'hex');
   299|  const expected = Buffer.from(record.passwordHash, 'hex');
   300|  if (candidate.length !== expected.length) return null;
   301|  return timingSafeEqual(candidate, expected) ? record.id : null;
   302|}
