   532|/** Verify a member's email + password.
   533| *  - First checks the durable fallback store (scrypt-hashed passwords).
   534| *  - Falls back to Supabase Auth signInWithPassword when no fallback record exists.
   535| *  Records last_login_at on success. Never returns the password or session token. */
   536|export async function loginMember(email: string, password: string): Promise<MemberLoginResult> {
   537|  const normalizedEmail = email.trim().toLowerCase();
   538|  if (!normalizedEmail || !password) {
   539|    return { success: false, message: 'Email and password are required.', deploymentMarker: DEPLOYMENT_MARKER };
   540|  }
   541|
   542|  // 1. Durable fallback store first (covers members registered during Supabase email rate-limit).
   543|  const fallbackUserId = await verifyFallbackMemberPassword(normalizedEmail, password);
   544|  if (fallbackUserId) {
   545|    await updateMemberLastLogin(fallbackUserId);
   546|    try {
   547|      const supabase = getSupabaseAdmin();
   548|      await supabase.from('audit_logs').insert({
   549|        user_id: fallbackUserId,
   550|        action: 'member_login',
   551|        details: JSON.stringify({ source: 'fallback_store', email: normalizedEmail }),
   552|        created_at: new Date().toISOString(),
   553|      });
   554|    } catch { /* non-critical */ }
   555|    return { success: true, message: 'Login successful.', userId: fallbackUserId, email: normalizedEmail, deploymentMarker: DEPLOYMENT_MARKER };
   556|  }
   557|
   558|  // 2. Supabase Auth path.
   559|  try {
   560|    const supabase = getSupabaseAdmin();
   561|    const { data, error } = await supabase.auth.signInWithPassword({
   562|      email: normalizedEmail,
   563|      password,
   564|    });
   565|    if (error) {
   566|      const msg = error.message.toLowerCase();
   567|      if (msg.includes('invalid login credentials') || msg.includes('invalid credentials')) {
   568|        return { success: false, message: 'Invalid email or password.', deploymentMarker: DEPLOYMENT_MARKER };
   569|      }
   570|      if (msg.includes('email not confirmed')) {
   571|        return { success: false, message: 'Please verify your email before signing in.', requiresVerification: true, deploymentMarker: DEPLOYMENT_MARKER };
   572|      }
   573|      if (msg.includes('rate limit')) {
   574|        return { success: false, message: 'Too many attempts. Please wait a minute and try again.', deploymentMarker: DEPLOYMENT_MARKER };
   575|      }
   576|      return { success: false, message: `Login failed: ${error.message}`, deploymentMarker: DEPLOYMENT_MARKER };
   577|    }
   578|    const userId = data.user?.id;
