   580|      return { success: false, message: 'Login succeeded but no user id returned.', deploymentMarker: DEPLOYMENT_MARKER };
   581|    }
   582|    await updateMemberLastLogin(userId);
   583|    // Best-effort audit log (does not block login).
   584|    try {
   585|      await supabase.from('audit_logs').insert({
   586|        user_id: userId,
   587|        action: 'member_login',
   588|        details: JSON.stringify({ source: 'supabase_auth', email: normalizedEmail }),
   589|        created_at: new Date().toISOString(),
   590|      });
   591|    } catch { /* non-critical */ }
   592|    return { success: true, message: 'Login successful.', userId, email: normalizedEmail, deploymentMarker: DEPLOYMENT_MARKER };
   593|  } catch (err) {
   594|    const message = err instanceof Error ? err.message : 'Login failed due to an internal error.';
   595|    console.error('[MemberDB] Login exception:', message);
