   600|/** Request a member password reset.
   601| *  - For fallback-store members: verifies the member exists, then issues a
   602| *    single-use reset token (random) stored alongside the record. The token
   603| *    is returned once so the caller (owner/admin) can deliver it via the
   604| *    chosen channel. The password itself is never reset here.
   605| *  - For Supabase Auth members: triggers Supabase resetPasswordForEmail.
   606| *  Always returns success:true for unknown emails to avoid user enumeration. */
   607|export interface MemberResetResult {
   608|  success: boolean;
   609|  message: string;
   610|  resetToken?: string;
   611|  channel?: 'fallback_store' | 'supabase_email';
   612|  deploymentMarker: string;
   613|}
   614|
   615|export async function requestMemberPasswordReset(email: string): Promise<MemberResetResult> {
   616|  const normalizedEmail = email.trim().toLowerCase();
   617|  if (!normalizedEmail) {
   618|    return { success: false, message: 'Email is required.', deploymentMarker: DEPLOYMENT_MARKER };
   619|  }
   620|
   621|  // 1. Fallback store member?
   622|  const store = await readMemberStore();
   623|  const fallbackRecord = Object.values(store).find((m) => m.email === normalizedEmail);
   624|  if (fallbackRecord) {
   625|    const token = randomBytes(24).toString('hex');
   626|    const now = new Date().toISOString();
   627|    const expiresAt = Date.now() + 30 * 60 * 1000; // 30 minutes
   628|    (store[fallbackRecord.id] as FallbackMemberRecord & { resetToken?: string; resetTokenExpiresAt?: number }).resetToken = token;
   629|    (store[fallbackRecord.id] as FallbackMemberRecord & { resetTokenExpiresAt?: number }).resetTokenExpiresAt = expiresAt;
   630|    store[fallbackRecord.id].updatedAt = now;
   631|    await writeMemberStore(store);
   632|    try {
   633|      const supabase = getSupabaseAdmin();
   634|      await supabase.from('audit_logs').insert({
   635|        user_id: fallbackRecord.id,
   636|        action: 'member_password_reset_requested',
   637|        details: JSON.stringify({ email: normalizedEmail, channel: 'fallback_store' }),
   638|        created_at: now,
   639|      });
   640|    } catch { /* non-critical */ }
   641|    return { success: true, message: 'Reset token issued. Deliver it to the member via a verified channel.', resetToken: token, channel: 'fallback_store', deploymentMarker: DEPLOYMENT_MARKER };
   642|  }
   643|
   644|  // 2. Supabase Auth member — trigger email reset.
   645|  try {
   646|    const supabase = getSupabaseAdmin();
   647|    const { error } = await supabase.auth.resetPasswordForEmail(normalizedEmail);
   648|    if (error) {
   649|      // Avoid user enumeration: still return success for unknown emails.
   650|      if (error.message.toLowerCase().includes('rate limit')) {
   651|        return { success: false, message: 'Too many reset requests. Please wait a minute and try again.', deploymentMarker: DEPLOYMENT_MARKER };
   652|      }
   653|      // Most other errors are not user-facing.
   654|      console.error('[MemberDB] Supabase reset error:', error.message);
   655|    }
   656|    return { success: true, message: 'If an account exists for that email, a reset link has been sent.', channel: 'supabase_email', deploymentMarker: DEPLOYMENT_MARKER };
   657|  } catch (err) {
   658|    const message = err instanceof Error ? err.message : 'Reset request failed.';
   659|    console.error('[MemberDB] Reset exception:', message);
   660|    return { success: false, message, deploymentMarker: DEPLOYMENT_MARKER };
   661|  }
   662|}
