   664|/** Reset a fallback-store member's password using a single-use token. */
   665|export async function resetMemberPasswordWithToken(email: string, token: string, newPassword: string): Promise<MemberResetResult> {
   666|  const normalizedEmail = email.trim().toLowerCase();
   667|  if (!normalizedEmail || !token || !newPassword) {
   668|    return { success: false, message: 'Email, token, and new password are required.', deploymentMarker: DEPLOYMENT_MARKER };
   669|  }
   670|  if (newPassword.length < 8 || !/[A-Z]/.test(newPassword) || !/[0-9]/.test(newPassword)) {
   671|    return { success: false, message: 'Password must be at least 8 characters with 1 uppercase letter and 1 number.', deploymentMarker: DEPLOYMENT_MARKER };
   672|  }
   673|  const store = await readMemberStore();
   674|  const record = Object.values(store).find((m) => m.email === normalizedEmail) as (FallbackMemberRecord & { resetToken?: string; resetTokenExpiresAt?: number }) | undefined;
   675|  if (!record || !record.resetToken || record.resetToken !== token) {
   676|    return { success: false, message: 'Invalid or expired reset token.', deploymentMarker: DEPLOYMENT_MARKER };
   677|  }
   678|  if (!record.resetTokenExpiresAt || record.resetTokenExpiresAt < Date.now()) {
   679|    return { success: false, message: 'Reset token has expired. Please request a new one.', deploymentMarker: DEPLOYMENT_MARKER };
   680|  }
   681|  const salt = randomBytes(16).toString('hex');
   682|  record.passwordHash = hashPassword(newPassword, salt);
   683|  record.passwordSalt = salt;
   684|  record.resetToken = undefined;
   685|  record.resetTokenExpiresAt = undefined;
   686|  record.updatedAt = new Date().toISOString();
   687|  store[record.id] = record;
   688|  await writeMemberStore(store);
   689|  try {
   690|    const supabase = getSupabaseAdmin();
   691|    await supabase.from('audit_logs').insert({
   692|      user_id: record.id,
   693|      action: 'member_password_reset_completed',
   694|      details: JSON.stringify({ email: normalizedEmail, channel: 'fallback_store' }),
