   153|/**
   154| * Calculate the payment amount for a tokenized investment.
   155| * Server reads share_price from the deal — NEVER trusts client-submitted price.
   156| */
   157|export async function calculateTokenizedAmount(
   158|  dealId: string,
   159|  shareCount: number,
   160|): Promise<{ amountCents: number; sharePrice: number; ok: boolean; error?: string }> {
   161|  const sb = getSB();
   162|  const { data: deal, error } = await sb.from('jv_deals')
   163|    .select('share_price, available_shares, minimum_shares, maximum_shares_per_investor, tokenized_status, tokenized_enabled')
   164|    .eq('id', dealId)
   165|    .single();
   166|
   167|  if (error || !deal) {
   168|    return { amountCents: 0, sharePrice: 0, ok: false, error: 'Deal not found' };
   169|  }
   170|
   171|  if (!deal.tokenized_enabled) {
   172|    return { amountCents: 0, sharePrice: 0, ok: false, error: 'Tokenized pathway not enabled for this deal' };
   173|  }
   174|
   175|  if (deal.tokenized_status !== 'TOKENIZED_OPEN') {
   176|    return { amountCents: 0, sharePrice: 0, ok: false, error: `Tokenized status is ${deal.tokenized_status}` };
   177|  }
   178|
   179|  if (shareCount < (deal.minimum_shares || 1)) {
   180|    return { amountCents: 0, sharePrice: deal.share_price || 50, ok: false, error: `Minimum shares is ${deal.minimum_shares || 1}` };
   181|  }
   182|
   183|  if (shareCount > (deal.available_shares || 0)) {
   184|    return { amountCents: 0, sharePrice: deal.share_price || 50, ok: false, error: 'Exceeds available shares' };
   185|  }
   186|
   187|  if (deal.maximum_shares_per_investor > 0 && shareCount > deal.maximum_shares_per_investor) {
   188|    return { amountCents: 0, sharePrice: deal.share_price || 50, ok: false, error: 'Exceeds maximum shares per investor' };
   189|  }
   190|
   191|  const sharePrice = Number(deal.share_price) || 50;
   192|  const amountCents = Math.round(shareCount * sharePrice * 100);
   193|
   194|  return { amountCents, sharePrice, ok: true };
   195|}
