   213|
   214|  const minCents = Number(deal.jv_minimum_contribution) * 100 || 2_000_000;
   215|  if (amountCents < minCents) {
   216|    return { ok: false, error: `Minimum JV contribution is $${(minCents / 100).toLocaleString()}` };
