    67|export const ALLOWED_TRANSITIONS: Readonly<Record<BusinessStatus, readonly BusinessStatus[]>> = {
    68|  DISCOVERED: ['CONTACT_VERIFIED', 'INVALID', 'DUPLICATE', 'TEST'],
    69|  CONTACT_VERIFIED: ['OWNER_APPROVED_FOR_OUTREACH', 'DO_NOT_CONTACT', 'INVALID', 'DUPLICATE'],
    70|  OWNER_APPROVED_FOR_OUTREACH: ['CONTACTED', 'DO_NOT_CONTACT'],
    71|  CONTACTED: ['DELIVERED', 'REPLIED', 'DO_NOT_CONTACT'],
    72|  DELIVERED: ['REPLIED', 'DO_NOT_CONTACT'],
    73|  REPLIED: ['INTERESTED', 'DO_NOT_CONTACT'],
    74|  INTERESTED: ['QUALIFIED', 'DO_NOT_CONTACT'],
    75|  QUALIFIED: ['COMMITTED', 'DO_NOT_CONTACT'],
    76|  COMMITTED: ['FUNDED', 'DO_NOT_CONTACT'],
    77|  FUNDED: [],
