    84|/**
    85| * Check whether a status transition is allowed.
    86| * Returns true only if `to` is in ALLOWED_TRANSITIONS[from].
    87| */
    88|export function isTransitionAllowed(from: BusinessStatus, to: BusinessStatus): boolean {
    89|  const allowed = ALLOWED_TRANSITIONS[from] ?? [];
    90|  return allowed.includes(to);
