    92|
    93|/**
    94| * Attempt a status transition. Throws on invalid transitions.
    95| * The error message names the rule violated so tests can assert on it.
    96| */
    97|export function assertValidTransition(from: BusinessStatus, to: BusinessStatus): void {
    98|  if (from === to) {
    99|    throw new Error(`Invalid transition: ${from} → ${to} (no-op transition not allowed).`);
   100|  }
   101|  if (!isTransitionAllowed(from, to)) {
   102|    throw new Error(
   103|      `Invalid transition: ${from} → ${to}. ` +
   104|      `Allowed next stages from ${from}: [${(ALLOWED_TRANSITIONS[from] ?? []).join(', ')}]. ` +
   105|      ruleViolation(from, to),
   106|    );
   107|  }
   108|}
   109|
   110|/** Human-readable rule-violation explanation for each forbidden jump. */
   111|function ruleViolation(from: BusinessStatus, to: BusinessStatus): string {
   112|  // Discovered is not contacted.
   113|  if (from === 'DISCOVERED' && (to === 'CONTACTED' || to === 'DELIVERED' || to === 'REPLIED')) {
   114|    return `Rule violated: Discovered is not contacted.`;
   115|  }
   116|  // Contacted is not interested.
   117|  if (from === 'CONTACTED' && (to === 'INTERESTED' || to === 'QUALIFIED' || to === 'COMMITTED' || to === 'FUNDED')) {
   118|    return `Rule violated: Contacted is not interested.`;
   119|  }
   120|  // Interested is not qualified.
   121|  if (from === 'INTERESTED' && (to === 'COMMITTED' || to === 'FUNDED')) {
   122|    return `Rule violated: Interested is not qualified.`;
   123|  }
   124|  // Qualified is not committed.
   125|  if (from === 'QUALIFIED' && to === 'FUNDED') {
   126|    return `Rule violated: Qualified is not committed.`;
   127|  }
   128|  // Committed is not funded (must pass through the funding step, but
   129|  // COMMITTED → FUNDED IS allowed above; this guards reverse jumps).
   130|  if (to === 'FUNDED' && from !== 'COMMITTED') {
   131|    return `Rule violated: Committed is not funded (only COMMITTED may advance to FUNDED).`;
   132|  }
   133|  return `This transition skips required pipeline stages.`;
