   348|/**
   349| * Transition a record's status. Enforces transition rules.
   350| * Non-owner transitions follow the funnel. Owner may override with evidence.
   351| */
   352|export async function transitionStatus(
   353|  id: string,
   354|  toStatus: BusinessStatus,
   355|  options: {
   356|    changedBy?: string;
   357|    reason?: string;
   358|    evidenceUrl?: string | null;
   359|    isOwnerOverride?: boolean;
   360|  } = {},
   361|): Promise<{ ok: true; record: BusinessRecord } | { ok: false; error: string }> {
   362|  if (!ALL_BUSINESS_STATUSES.includes(toStatus)) {
   363|    return { ok: false, error: `Invalid status: ${toStatus}.` };
   364|  }
   365|
   366|  const store = await loadStore();
   367|  const record = store.records.find((r) => r.id === id);
   368|  if (!record) return { ok: false, error: `Record not found: ${id}` };
   369|
   370|  const fromStatus = record.status;
   371|  const isOwnerOverride = options.isOwnerOverride ?? false;
   372|
   373|  // Owner override with evidence may bypass transition rules.
   374|  if (isOwnerOverride) {
   375|    if (!options.evidenceUrl) {
   376|      return { ok: false, error: 'Owner override requires evidenceUrl.' };
   377|    }
   378|    // Owner can move to any status, but it's logged with evidence.
   379|  } else {
   380|    // Enforce transition rules for non-owner transitions.
   381|    try {
   382|      assertValidTransition(fromStatus, toStatus);
   383|    } catch (err) {
   384|      return { ok: false, error: err instanceof Error ? err.message : 'Invalid transition.' };
   385|    }
   386|  }
   387|
   388|  // DO_NOT_CONTACT records cannot enter outreach.
   389|  if (fromStatus === 'DO_NOT_CONTACT' && toStatus === 'OWNER_APPROVED_FOR_OUTREACH') {
   390|    if (!isOwnerOverride) {
   391|      return { ok: false, error: 'DO_NOT_CONTACT records cannot enter outreach.' };
   392|    }
   393|  }
   394|
   395|  const now = nowIso();
   396|  const historyEntry: StatusHistoryEntry = {
   397|    from: fromStatus,
   398|    to: toStatus,
   399|    changedAt: now,
   400|    changedBy: options.changedBy ?? 'system',
   401|    reason: options.reason ?? (isOwnerOverride ? 'Owner override with evidence.' : 'Pipeline transition.'),
   402|    evidenceUrl: options.evidenceUrl ?? null,
   403|    isOwnerOverride,
   404|  };
   405|
   406|  record.status = toStatus;
   407|  record.updatedAt = now;
   408|  record.statusHistory.push(historyEntry);
   409|
   410|  await saveStore(store);
   411|  await appendDurableEvent('business-classification/records', {
   412|    type: 'transition',
   413|    id,
   414|    from: fromStatus,
   415|    to: toStatus,
   416|    at: now,
   417|    isOwnerOverride,
   418|  });
   419|
   420|  return { ok: true, record };
