if token:
    with open('/tmp/owner_token.txt','w') as f: f.write(token)
print(f'Owner token: {token[:15]}...{token[-4:] if token else "NONE"}')

# 2. Ping the service awake and verify health
import urllib.request as ur
try:
    r = ur.urlopen(f'{BASE}/health', timeout=10, context=ctx)
    h = json.loads(r.read().decode())
    print(f'Health: {h.get("status")} | commit: {h.get("commit","?")[:12]} | routes: {len(h.get("routes",[]))}')
except Exception as e:
    print(f'Health error: {e}')
